#!/usr/bin/env python3
"""Offline SIP identity boundary processor (PROTOCOL.md, revision 1).

Reads one JSON object describing a batch of jobs from stdin and writes one
JSON object holding one decision per job to stdout.  Everything is computed
from the trusted directory/account/gateway context plus the (untrusted) SIP
request text; no network or other external input is used.
"""

import json
import os
import re
import string
import sys

# ---------------------------------------------------------------------------
# constants and character classes
# ---------------------------------------------------------------------------

ANON = "sip:anonymous@anonymous.invalid"
MAX_TEXT = 32768
MAX_LINES = 512
MAX_FIELDS = 128
MAX_CSEQ = 2147483647

_LET = string.ascii_letters
_DIG = string.digits
TOKEN_CHARS = frozenset(_LET + _DIG + "-.!%*_+`'~")
USER_CHARS = frozenset(_LET + _DIG + "-_.!~*'()+")
HOST_CHARS = frozenset(_LET + _DIG + "-.")
ALNUM = frozenset(_LET + _DIG)
HEX = frozenset("0123456789abcdefABCDEF")
DEC = frozenset(_DIG)
WSP = " \t"

_T = r"[A-Za-z0-9\-\.!%*_\+`'~]"
RE_NAME = re.compile(_T + r"+[ \t]*:")
RE_DISPLAY = re.compile(r"(?:" + _T + r"+(?:[ \t]+" + _T + r"+)*)?[ \t]*\Z")
RE_CALLID = re.compile(r"[A-Za-z0-9_.@+\-]{1,128}\Z")
RE_CSEQ = re.compile(r"([0-9]+)[ \t]+([^ \t]+)\Z")
RE_BAD = re.compile(r"[^\t\r\n -~]")

COMPACT = {
    "f": "from",
    "t": "to",
    "i": "call-id",
    "l": "content-length",
    "c": "content-type",
}
SINGLETONS = frozenset((
    "from", "to", "call-id", "cseq", "content-length",
    "p-preferred-identity", "remote-party-id", "privacy", "content-type",
))


class Reject(Exception):
    """A job-level decision with a fixed reason string."""

    __slots__ = ("reason",)

    def __init__(self, reason):
        Exception.__init__(self, reason)
        self.reason = reason


# ---------------------------------------------------------------------------
# URI parsing / normalization
# ---------------------------------------------------------------------------

def _norm_host(host):
    """Validate a DNS host and return its canonical lowercase form."""
    core = host[:-1] if host.endswith(".") else host
    if not core or len(core) > 253:
        raise Reject("syntax")
    for label in core.split("."):
        if not 1 <= len(label) <= 63:
            raise Reject("syntax")
        if label[0] not in ALNUM or label[-1] not in ALNUM:
            raise Reject("syntax")
    return core.lower()


def _parse_sip(text, pos):
    n = len(text)
    out = []
    i = pos
    while i < n:
        ch = text[i]
        if ch in USER_CHARS:
            out.append(ch)
            i += 1
        elif ch == "%":
            if i + 3 > n or text[i + 1] not in HEX or text[i + 2] not in HEX:
                raise Reject("syntax")
            dec = chr(int(text[i + 1:i + 3], 16))
            if dec not in USER_CHARS:
                raise Reject("syntax")
            out.append(dec)
            i += 3
        else:
            break
    if i == pos:
        raise Reject("syntax")
    if i >= n or text[i] != "@":
        raise Reject("syntax")
    i += 1
    start = i
    while i < n and text[i] in HOST_CHARS:
        i += 1
    if i == start:
        raise Reject("syntax")
    return "sip:" + "".join(out) + "@" + _norm_host(text[start:i]), i


def _parse_tel(text, pos):
    n = len(text)
    if pos >= n or text[pos] != "+":
        raise Reject("syntax")
    i = pos + 1
    start = i
    while i < n and text[i] in DEC:
        i += 1
    digits = text[start:i]
    if not 1 <= len(digits) <= 15:
        raise Reject("syntax")
    if digits[0] == "0":
        raise Reject("syntax")
    return "tel:+" + digits, i


def parse_uri(text, pos):
    """Parse a sip or tel URI at text[pos]; return (normalized, end index)."""
    if pos + 4 <= len(text):
        scheme = text[pos:pos + 4].lower()
        if scheme == "sip:":
            return _parse_sip(text, pos + 4)
        if scheme == "tel:":
            return _parse_tel(text, pos + 4)
    raise Reject("syntax")


# ---------------------------------------------------------------------------
# address / display-name parsing
# ---------------------------------------------------------------------------

def _end_quoted(text, pos):
    """Return the index just past a quoted string starting at text[pos]."""
    n = len(text)
    i = pos + 1
    while i < n:
        ch = text[i]
        if ch == "\\":
            if i + 1 >= n:
                raise Reject("syntax")
            nxt = text[i + 1]
            if nxt != "\t" and not " " <= nxt <= "~":
                raise Reject("syntax")
            i += 2
        elif ch == '"':
            return i + 1
        else:
            i += 1
    raise Reject("syntax")


def _parse_tag_tail(text, pos):
    """Parse an optional ';tag=TOKEN' header parameter at text[pos]."""
    n = len(text)
    i = pos
    while i < n and text[i] in WSP:
        i += 1
    if i >= n:
        return None
    if text[i] != ";":
        raise Reject("syntax")
    i += 1
    while i < n and text[i] in WSP:
        i += 1
    start = i
    while i < n and text[i] in TOKEN_CHARS:
        i += 1
    if text[start:i].lower() != "tag":
        raise Reject("syntax")
    while i < n and text[i] in WSP:
        i += 1
    if i >= n or text[i] != "=":
        raise Reject("syntax")
    i += 1
    while i < n and text[i] in WSP:
        i += 1
    tstart = i
    while i < n and text[i] in TOKEN_CHARS:
        i += 1
    tag = text[tstart:i]
    if not 1 <= len(tag) <= 128:
        raise Reject("syntax")
    while i < n and text[i] in WSP:
        i += 1
    if i != n:
        raise Reject("syntax")
    return tag


def parse_address(text, allow_tag):
    """Parse exactly one address; return (normalized URI, tag or None)."""
    n = len(text)
    if not text:
        raise Reject("syntax")
    pos = 0
    if text[0] == '"':
        pos = _end_quoted(text, 0)
        i = pos
        while i < n and text[i] in WSP:
            i += 1
        if i >= n or text[i] != "<":
            raise Reject("syntax")
        pos = i + 1
    elif "<" in text:
        cut = text.index("<")
        if not RE_DISPLAY.match(text[:cut]):
            raise Reject("syntax")
        pos = cut + 1
    else:
        uri, end = parse_uri(text, 0)
        if allow_tag:
            return uri, _parse_tag_tail(text, end)
        if end != n:
            raise Reject("syntax")
        return uri, None

    i = pos
    while i < n and text[i] in WSP:
        i += 1
    uri, i = parse_uri(text, i)
    while i < n and text[i] in WSP:
        i += 1
    if i >= n or text[i] != ">":
        raise Reject("syntax")
    i += 1
    if allow_tag:
        return uri, _parse_tag_tail(text, i)
    if i != n:
        raise Reject("syntax")
    return uri, None


def split_address_list(text):
    """Split a comma separated address list, honouring quotes and brackets."""
    members = []
    cur = []
    depth = 0
    in_quote = False
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if in_quote:
            cur.append(ch)
            if ch == "\\":
                if i + 1 < n:
                    cur.append(text[i + 1])
                    i += 1
            elif ch == '"':
                in_quote = False
            i += 1
            continue
        if ch == '"':
            in_quote = True
            cur.append(ch)
        elif ch == "<":
            depth += 1
            cur.append(ch)
        elif ch == ">":
            if depth > 0:
                depth -= 1
            cur.append(ch)
        elif ch == "," and depth == 0:
            members.append("".join(cur))
            cur = []
        else:
            cur.append(ch)
        i += 1
    members.append("".join(cur))
    return [member.strip(WSP) for member in members]


# ---------------------------------------------------------------------------
# request framing
# ---------------------------------------------------------------------------

class Parsed(object):
    __slots__ = ("method", "ruri", "furi", "ftag", "fanon", "turi", "ttag",
                 "callid", "cseq", "privacy", "ctype", "ppi", "rpid", "pai",
                 "body")


def parse_request(text):
    """Validate a whole request; return a Parsed object or raise Reject."""
    if len(text) > MAX_TEXT:
        raise Reject("syntax")
    if RE_BAD.search(text):
        raise Reject("syntax")
    sep = text.find("\r\n\r\n")
    if sep < 0:
        raise Reject("syntax")
    header = text[:sep]
    body = text[sep + 4:]
    probe = header.replace("\r\n", "")
    if "\r" in probe or "\n" in probe:
        raise Reject("syntax")
    lines = header.split("\r\n")
    if len(lines) > MAX_LINES:
        raise Reject("syntax")

    request_line = lines[0]
    parts = request_line.split(" ")
    if len(parts) != 3 or parts[2] != "SIP/2.0":
        raise Reject("syntax")
    method = parts[0]
    if method not in ("INVITE", "MESSAGE"):
        raise Reject("syntax")
    ruri, used = parse_uri(parts[1], 0)
    if used != len(parts[1]) or not ruri.startswith("sip:"):
        raise Reject("syntax")

    fields = []
    for line in lines[1:]:
        if line[:1] == " " or line[:1] == "\t":
            if not fields:
                raise Reject("syntax")
            fields[-1][1] += " " + line.lstrip(WSP)
        else:
            match = RE_NAME.match(line)
            if not match:
                raise Reject("syntax")
            fields.append([match.group(1), line[match.end():]])
    if len(fields) > MAX_FIELDS:
        raise Reject("syntax")

    values = {}
    pai_raw = []
    for name, value in fields:
        key = name.lower()
        key = COMPACT.get(key, key)
        clean = value.strip(WSP)
        if key == "p-asserted-identity":
            pai_raw.append(clean)
        elif key in SINGLETONS:
            if key in values:
                raise Reject("syntax")
            values[key] = clean

    for needed in ("from", "to", "call-id", "cseq", "content-length"):
        if needed not in values:
            raise Reject("syntax")

    match = RE_CSEQ.match(values["cseq"])
    if not match:
        raise Reject("syntax")
    cseq = int(match.group(1))
    if not 1 <= cseq <= MAX_CSEQ:
        raise Reject("syntax")
    if match.group(2) != method:
        raise Reject("syntax")

    callid = values["call-id"]
    if not RE_CALLID.match(callid):
        raise Reject("syntax")

    length = values["content-length"]
    if not length:
        raise Reject("syntax")
    for ch in length:
        if ch not in DEC:
            raise Reject("syntax")
    if int(length) != len(body):
        raise Reject("syntax")

    privacy = None
    if "privacy" in values:
        privacy = values["privacy"].lower()
        if privacy not in ("id", "none"):
            raise Reject("syntax")

    ctype = None
    if "content-type" in values:
        ctype = values["content-type"]
        if not ctype:
            raise Reject("syntax")

    parsed = Parsed()
    parsed.method = method
    parsed.ruri = ruri
    parsed.body = body
    parsed.callid = callid
    parsed.cseq = cseq
    parsed.privacy = privacy
    parsed.ctype = ctype

    parsed.furi, parsed.ftag = parse_address(values["from"], True)
    parsed.fanon = parsed.furi == ANON
    parsed.turi, parsed.ttag = parse_address(values["to"], True)

    parsed.ppi = None
    if "p-preferred-identity" in values:
        parsed.ppi = parse_address(values["p-preferred-identity"], False)[0]
        if parsed.ppi == ANON:
            raise Reject("syntax")
    parsed.rpid = None
    if "remote-party-id" in values:
        parsed.rpid = parse_address(values["remote-party-id"], False)[0]
        if parsed.rpid == ANON:
            raise Reject("syntax")

    pai = []
    for value in pai_raw:
        for member in split_address_list(value):
            uri = parse_address(member, False)[0]
            if uri == ANON:
                raise Reject("syntax")
            pai.append(uri)
    if not 1 <= len(pai) <= 2:
        raise Reject("syntax")
    if len(pai) == 2 and (pai[0].startswith("sip:") == pai[1].startswith("sip:")):
        raise Reject("syntax")
    parsed.pai = pai
    return parsed


# ---------------------------------------------------------------------------
# batch processing
# ---------------------------------------------------------------------------

def _domain_of(identity):
    if identity.startswith("sip:"):
        at = identity.find("@")
        if at > 4:
            return identity[at + 1:]
    return None


def process_batch(obj):
    if not isinstance(obj, dict):
        return {"results": []}
    directory = obj.get("directory")
    accounts = obj.get("accounts")
    gateways = obj.get("gateways")
    jobs = obj.get("jobs")
    if not isinstance(directory, dict):
        directory = {}
    if not isinstance(accounts, dict):
        accounts = {}
    if not isinstance(gateways, dict):
        gateways = {}
    if not isinstance(jobs, list):
        jobs = []

    alias = {}
    for identity, aliases in directory.items():
        if isinstance(identity, str):
            alias[identity] = identity
            if isinstance(aliases, list):
                for item in aliases:
                    if isinstance(item, str):
                        alias[item] = identity
    alias.pop(ANON, None)

    domain_cache = {}

    def domain_of(identity):
        dom = domain_cache.get(identity, 0)
        if dom == 0:
            dom = _domain_of(identity)
            domain_cache[identity] = dom
        return dom

    gateway_cache = {}

    def gateway_of(name):
        info = gateway_cache.get(name)
        if info is None:
            local = frozenset()
            peers = {}
            entry = gateways.get(name)
            if isinstance(entry, dict):
                doms = entry.get("local_domains")
                if isinstance(doms, list):
                    local = frozenset(x for x in doms if isinstance(x, str))
                peer_map = entry.get("peers")
                if isinstance(peer_map, dict):
                    for peer, listed in peer_map.items():
                        if isinstance(listed, list):
                            peers[peer] = frozenset(
                                x for x in listed if isinstance(x, str))
                        else:
                            peers[peer] = frozenset()
            info = (local, peers)
            gateway_cache[name] = info
        return info

    def account_of(subject):
        entry = accounts.get(subject)
        if not isinstance(entry, dict):
            return None
        primary = entry.get("primary")
        if not isinstance(primary, str):
            primary = None
        allowed = set()
        if primary is not None:
            allowed.add(primary)
        listing = entry.get("allow")
        if isinstance(listing, list):
            for item in listing:
                if isinstance(item, str):
                    allowed.add(item)
        return primary, frozenset(allowed)

    results = []
    wires = []
    for job in jobs:
        result, wire = decide(job, wires, alias, domain_of, gateway_of,
                              account_of, accounts)
        results.append(result)
        wires.append(wire)
    return {"results": results}


def decide(job, wires, alias, domain_of, gateway_of, account_of, accounts):
    reject = lambda reason: ({"status": "reject", "reason": reason}, None)

    if not isinstance(job, dict):
        return reject("syntax")

    if "raw" in job:
        text = job["raw"]
        if not isinstance(text, str):
            return reject("syntax")
    else:
        source = job.get("source")
        if isinstance(source, bool) or not isinstance(source, int):
            return reject("upstream")
        if source < 0 or source >= len(wires):
            return reject("upstream")
        text = wires[source]
        if text is None:
            return reject("upstream")

    try:
        parsed = parse_request(text)
    except Reject as exc:
        return reject(exc.reason)
    except Exception:
        return reject("syntax")

    ingress = job.get("ingress")
    kind = ingress.get("kind") if isinstance(ingress, dict) else None
    gateway_name = job.get("gateway")
    local, peers = gateway_of(gateway_name)

    if kind == "local":
        subject = ingress.get("subject") if isinstance(ingress, dict) else None
        if not isinstance(subject, str) or subject not in accounts:
            return reject("unauthenticated")
        account = account_of(subject)
        primary, allowed = account
        selected = None
        if not parsed.fanon:
            found = alias.get(parsed.furi)
            if found is None or found not in allowed or domain_of(found) not in local:
                return reject("identity")
            selected = found
        if parsed.ppi is not None:
            found = alias.get(parsed.ppi)
            if found is None or found not in allowed or domain_of(found) not in local:
                return reject("identity")
            selected = found
        if selected is None:
            selected = primary
        if selected is None or selected not in allowed or domain_of(selected) not in local:
            return reject("identity")
        basis = "local"
    elif kind == "peer":
        peer = ingress.get("name") if isinstance(ingress, dict) else None
        if not isinstance(peer, str) or peer not in peers:
            return reject("unauthenticated")
        if not parsed.pai:
            return reject("unauthenticated")
        authority = peers[peer]
        selected = None
        for claim in parsed.pai:
            found = alias.get(claim)
            if found is None or domain_of(found) not in authority:
                return reject("identity")
            if selected is None:
                selected = found
            elif selected != found:
                return reject("identity")
        if not parsed.fanon and alias.get(parsed.furi) != selected:
            return reject("identity")
        if parsed.ppi is not None and alias.get(parsed.ppi) != selected:
            return reject("identity")
        if parsed.rpid is not None and alias.get(parsed.rpid) != selected:
            return reject("identity")
        basis = "peer"
    else:
        return reject("unauthenticated")

    private = parsed.fanon or parsed.privacy == "id"
    trusted_out = job.get("trusted_out", False)
    emit_pai = (not private) or bool(trusted_out)

    from_uri = ANON if private else selected
    lines = [
        parsed.method + " " + parsed.ruri + " SIP/2.0",
        "From: <" + from_uri + (">;tag=" + parsed.ftag if parsed.ftag else ">"),
        "To: <" + parsed.turi + (">;tag=" + parsed.ttag if parsed.ttag else ">"),
        "Call-ID: " + parsed.callid,
        "CSeq: " + str(parsed.cseq) + " " + parsed.method,
        "Privacy: " + ("id" if private else "none"),
    ]
    if emit_pai:
        lines.append("P-Asserted-Identity: <" + selected + ">")
    if parsed.ctype is not None:
        lines.append("Content-Type: " + parsed.ctype)
    lines.append("Content-Length: " + str(len(parsed.body)))
    wire = "\r\n".join(lines) + "\r\n\r\n" + parsed.body

    return ({"status": "accept", "identity": selected, "basis": basis,
             "private": private, "wire": wire}, wire)


# ---------------------------------------------------------------------------
# entry point
# ---------------------------------------------------------------------------

def main():
    data = sys.stdin.buffer.read()
    try:
        obj = json.loads(data.decode("utf-8"))
    except Exception as exc:  # pragma: no cover - trusted, well formed input
        sys.stderr.write("input error: %r\n" % (exc,))
        os._exit(1)
    payload = json.dumps(process_batch(obj)).encode("utf-8") + b"\n"
    sys.stdout.buffer.write(payload)
    sys.stdout.buffer.flush()
    try:
        sys.stderr.flush()
    except Exception:
        pass
    os._exit(0)


if __name__ == "__main__":
    main()
